controls.old:
if occupied globals catalog family.Check.fam_name then Error (collision family.fam_name)
else
  let* provisional = Check.declare_family ~budget globals family in

controls.new:
let* checked =
          if occupied symbolic catalog member.Check.d_name then Error (collision member.d_name)
          else
            let* body = member.d_body |> Option.to_result
              ~none:(Check.missing_body member.d_name) in
            Ok (Global.add member.d_name (Global.Def { Global.ty = member.d_ty;
              def = body; reducible = true; rec_arg = None; partial = false }) symbolic) in
